html:
{% set company = frappe.get_doc("Company", doc.company) %}
{% set customer = frappe.get_doc("Customer", doc.customer) %}

{# ORPHAN CONTROL LOGIC #}
{% set base_chunk = 9 %}
{% set total_items_count = doc.items|length %}
{% set rem = total_items_count % base_chunk %}

{% if total_items_count > base_chunk and rem == 1 %}
    {% set chunk_size = base_chunk - 1 %}
{% else %}
    {% set chunk_size = base_chunk %}
{% endif %}

{% set chunks = (total_items_count // chunk_size) + (1 if total_items_count % chunk_size else 0) %}

<style>
@page { margin: 5mm; }
body, .print-format { margin:0; padding:0; font-family:Arial, sans-serif; font-size:10pt; color: #000; line-height: 1.2; }
.wrapper { width:100%; border:1px solid #000; box-sizing:border-box; position:relative; min-height: 100%; } 
.copy-label { position:absolute; top:5px; right:5px; font-size:9pt; font-weight:bold; border:1px solid #000; padding:2px 8px; background:#fff; z-index: 10; }

.header { border-bottom:1px solid #000; padding:8px; position:relative; }
.logo img { max-width:140px; max-height:85px; object-fit:contain; }
.company-name { font-weight:bold; font-size:14pt; }
.company-details { font-size:9pt; line-height:1.2; }

.info { border-bottom:1px solid #000; display:flex; font-size:10pt; }
.info-left, .info-right { width:50%; padding:6px; vertical-align: top; }
.info-left { border-right:1px solid #000; }
.info-label { font-weight:bold; width:90px; display:inline-block; }

/* TABLE BORDER FIXES */
table.items { width:100%; border-collapse: collapse; table-layout:fixed; }
.items th, .items td { border: 1px solid #000; padding: 6px 4px; word-wrap: break-word; vertical-align: top; }
.items th { background: #f2f2f2; font-weight: bold; text-align: center; font-size: 10pt; }
.items td { font-size: 9.5pt; }
.items td.text-center { text-align: center; }
.items td.text-right { text-align: right; }
.items td.bold { font-weight: bold; }

.final-content-area { page-break-inside: avoid; break-inside: avoid; }
.taxes-calc { border-bottom:1px solid #000; padding:6px; }
.summary { display:flex; border-bottom:1px solid #000; }
.summary-left { width:55%; padding:6px; border-right:1px solid #000; font-size: 9pt; }
.summary-right { width:45%; padding:6px; }
.summary-right table { width:100%; border-collapse:collapse; }
.value { text-align:right; font-weight:bold; }

.in-words { border-bottom:1px solid #000; padding:8px; font-size:9pt; font-weight:bold; font-style: italic; }
.bank-details-line { border-bottom:1px solid #000; padding:8px; font-size:9pt; }
.footer { display: flex; font-size: 9pt; }
.footer-left { flex: 1; padding: 8px; border-right: 1px solid #000; }
.footer-right { width: 35%; text-align: center; padding: 8px; display: flex; flex-direction: column; justify-content: flex-end; }

.page-info { position: absolute; top: 105px; right: 10px; font-size: 8.5pt; }
.page-break { page-break-before: always; }
</style>

{% for page_num in range(chunks) %}
<div class="wrapper">

  <!-- Header -->
  <div class="header">
    <div style="display:flex; justify-content:space-between; align-items:center;">
        <div class="logo"><img src="/files/Dacs inc Logo.jpeg" alt="Logo"></div>
        <div style="flex-grow:1; padding-left:20px;">
            <div class="company-name">{{ company.name }}</div>
            <div class="company-details">
                Jaya Sai Towers No.40, 1st & 2nd floor, Sajjan Rao Road, Parvathipuram,<br>
                V.V.Puram, BANGALORE - 560004 | GSTIN: 29AAIFD5710C1ZQ<br>
                Phone: 080-41234140 | Email: marketing@dacsinc.in
            </div>
        </div>
    </div>
     <div style="text-align:center; border-top:1.5px solid #000; padding-top:6px; margin-top:8px;">
        <strong style="font-size:13pt; ">SALES ORDER</strong><br>
        <span style="font-size: 10pt;">No: <strong>{{ doc.name }}</strong> | Date: <strong>{{ frappe.utils.formatdate(doc.transaction_date, "dd-MMM-yyyy") }}</strong></span>
    </div>
    <div class="page-info">Page {{ page_num + 1 }} of {{ chunks }}</div>
  </div>

  <!-- Customer Section -->
  <div class="info">
    <div class="info-left">
      <strong>M/s. {{ doc.customer_name }}</strong>
      <div style="margin-top:5px; font-size: 9pt;">{{ doc.address_display or "" }}</div>
      <div style="margin-top:5px;"><strong>GSTIN:</strong> {{ customer.gstin or "N/A" }}</div>
    </div>
    <div class="info-right">
      <div style="margin-bottom:2px;"><span class="info-label">Contact</span>: {{ doc.contact_person or "-" }}</div>
      <div style="margin-bottom:2px;"><span class="info-label">Mobile No</span>: {{ doc.contact_mobile or customer.mobile_no or "-" }}</div>
      <div style="margin-bottom:2px;"><span class="info-label">Email ID</span>: {{ doc.contact_email or customer.email_id or "-" }}</div>
    </div>
  </div>

  <!-- Items Table -->
  <table class="items">
    <thead>
      <tr>
       <th style="width: 35px;">Sl</th>
        <th style="width: 120px;">Item Code</th>
        <th style="width: 165px;">Description</th>
        <th style="width: 60px;">HSN</th>
        <th style="width: 45px;">Qty</th>
        <th style="width: 60px;">Rate</th>
        <th style="width: 90px;">Tax%</th>
        <th style="width: 80px;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% set start = page_num * chunk_size %}
      {% set end = (page_num + 1) * chunk_size %}
      {% set items_on_page = doc.items[start:end] %}

      {% for item in items_on_page %}
      <tr>
        <td class="text-center">{{ loop.index + start }}</td>
        <td class="bold">{{ item.item_code }}</td>
        <td>{{ item.description or item.item_name }}</td>
        <td class="text-center">{{ item.gst_hsn_code or "" }}</td>
        <td class="text-center">{{ item.qty | float }} ({{ item.uom }})</td>
        <td class="text-right">{{ "{:,.2f}".format(item.rate | float) }}</td>
        <td class="text-center">{{ item.item_tax_template }}</td>
        <td class="text-right"><strong>{{ "{:,.2f}".format(item.amount | float) }}</strong></td>
      </tr>
      {% endfor %}

      {# Layout Spacer for pagination consistency #}
      {% if items_on_page|length < chunk_size and page_num + 1 < chunks %}
          {% for i in range(chunk_size - items_on_page|length) %}
          <tr>
            <td style="height: 25px;">&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>
          </tr>
          {% endfor %}
      {% endif %}
    </tbody>
  </table>

  {% if page_num + 1 == chunks %}
  <div class="final-content-area">
    <div class="taxes-calc">
      <div style="font-weight: bold; font-size: 10pt; margin-bottom: 2px;">GST Breakup:</div>
      <div style="font-size: 8.5pt;">{{ doc.other_charges_calculation | safe }}</div>
    </div>

    <div class="summary">
      <div class="summary-left">
        <strong>Total Items:</strong> {{ doc.items|length }} | <strong>Total Quantity:</strong> {{ doc.total_qty | float or 0 }}
        <br><strong>Remark:</strong> 
      </div>
      <div class="summary-right">
        <table>
          <tr><td>Net Total</td><td class="value">{{ "{:,.2f}".format(doc.net_total | float) }}</td></tr>
          {% for tax in doc.taxes if tax.tax_amount != 0 %}
            <tr><td>{{ tax.account_head.split(' - ')[0] }}</td><td class="value">{{ "{:,.2f}".format(tax.tax_amount | float) }}</td></tr>
          {% endfor %}
          {% if doc.rounding_adjustment %}
            <tr><td>Round Off</td><td class="value">{{ "{:,.2f}".format(doc.rounding_adjustment | float) }}</td></tr>
          {% endif %}
          <tr style="border-top: 1.5px solid #000;"><td style="font-weight:bold; font-size:11.5pt; padding-top:5px;">Grand Total</td><td class="value" style="font-size: 11.5pt; padding-top:5px;">INR {{ "{:,.2f}".format(doc.rounded_total or doc.grand_total) }}</td></tr>
        </table>
      </div>
    </div>
  <div class="in-words">Amount in Words: {{ frappe.utils.money_in_words(doc.rounded_total or doc.grand_total) }}</div>

    <div class="bank-details-line">
        {% set bank_parts = [] %}
        {% set company_banks = frappe.get_doc("Company", doc.company).bank_details_for_printing %}
        {% if company_banks %}
            {% for d in company_banks %}
              {% if d.print_label %}{% set _ = bank_parts.append("<strong>" + d.print_label + ":</strong> " + d.print_value) %}{% endif %}
            {% endfor %}
            {{ bank_parts | join(" | ") | safe }}
        {% endif %}
    </div>

    <div class="footer">
        <div class="footer-left">
          <strong>Terms & Conditions:</strong><br>
          <div style="margin-top:3px;">
          {{ doc.terms | replace("\n", "<br>") | safe if doc.terms else "-" }}
          </div>
        </div>
        <div class="footer-right">
            For <strong>{{ doc.company }}</strong><br><br><br><br><br><br><br><br><br><br>
            <div style="border-bottom:1px solid #000; width:90%; margin:0 auto;"></div>
            Authorised Signatory
        </div>
    </div>
  </div>
  {% endif %}
</div>

{% if not outer_loop_index == copy_list|length or not inner_loop_index == chunks %}
<div class="page-break"></div>
  {% endif %}
</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}

{% endfor %}
